const supabaseUrl = $env.VITE_SUPABASE_URL || 'https://tu-proyecto.supabase.co';
const supabaseKey = $env.VITE_SUPABASE_ANON_KEY || 'tu-anon-key';

try {
  const today = new Date().toISOString().split('T')[0];
  let url = `${supabaseUrl}/rest/v1/appointments?status=eq.Disponible&appointment_date=gte.${today}&select=*,services(name),professionals(full_name)`;

  // Intentar leer argumentos opcionales pasados por el agente
  if (typeof fecha === 'string' && fecha.match(/^\d{4}-\d{2}-\d{2}$/)) {
    url += `&appointment_date=eq.${fecha}`;
  }

  const response = await fetch(url, {
    headers: {
      "apikey": supabaseKey,
      "Authorization": `Bearer ${supabaseKey}`
    }
  });
  if (!response.ok) throw new Error(`HTTP error ${response.status}`);
  const data = await response.json();

  return data.map(d => ({
    appointment_id: d.id,
    fecha: d.appointment_date,
    hora: d.appointment_time ? d.appointment_time.substring(0, 5) : '',
    duracion: `${d.duration_minutes} min`,
    precio: d.price,
    tratamiento: d.services ? d.services.name : 'Tratamiento',
    profesional: d.professionals ? d.professionals.full_name : 'Por asignar'
  }));
} catch (error) {
  return { error: error.message };
}

const supabaseUrl = $env.VITE_SUPABASE_URL || 'https://tu-proyecto.supabase.co';
const supabaseKey = $env.VITE_SUPABASE_ANON_KEY || 'tu-anon-key';
// La clave service role se usa en backend para bypass RLS y crear clientes si es necesario
const supabaseServiceKey = $env.SUPABASE_SERVICE_ROLE_KEY || supabaseKey;

// Parámetros que el agente conversacional debe pasar a la herramienta
const { appointment_id, customer_name, customer_phone, customer_email, notes } = arg1 || {};

if (!appointment_id || !customer_name || !customer_phone) {
  return { error: "Faltan argumentos requeridos: appointment_id, customer_name, customer_phone." };
}

try {
  // 1. Validar que el turno exista y esté Disponible
  const fetchAppRes = await fetch(`${supabaseUrl}/rest/v1/appointments?id=eq.${appointment_id}&select=*,services(name)`, {
    headers: { "apikey": supabaseKey, "Authorization": `Bearer ${supabaseKey}` }
  });
  const appData = await fetchAppRes.json();
  if (!appData || appData.length === 0) return { error: "El turno especificado no existe." };

  const appointment = appData[0];
  if (appointment.status !== 'Disponible') return { error: "Ese turno ya no está disponible. Elegí otra opción." };

  // 2. Buscar o crear cliente por teléfono
  const phoneSearchRes = await fetch(`${supabaseUrl}/rest/v1/clients?phone=eq.${encodeURIComponent(customer_phone.trim())}&select=*`, {
    headers: { "apikey": supabaseKey, "Authorization": `Bearer ${supabaseKey}` }
  });
  const clients = await phoneSearchRes.json();
  let client_id = null;
  const treatmentName = appointment.services ? appointment.services.name : 'Tratamiento';

  if (clients && clients.length > 0) {
    client_id = clients[0].id;
    const nextVisits = (clients[0].visit_count || 0) + 1;
    // Actualizar cliente existente
    await fetch(`${supabaseUrl}/rest/v1/clients?id=eq.${client_id}`, {
      method: 'PATCH',
      headers: {
        "apikey": supabaseServiceKey,
        "Authorization": `Bearer ${supabaseServiceKey}`,
        "Content-Type": "application/json",
        "Prefer": "return=minimal"
      },
      body: JSON.stringify({
        visit_count: nextVisits,
        status: 'Activo',
        last_treatment: treatmentName
      })
    });
  } else {
    // Crear nuevo cliente
    const newClientRes = await fetch(`${supabaseUrl}/rest/v1/clients`, {
      method: 'POST',
      headers: {
        "apikey": supabaseServiceKey,
        "Authorization": `Bearer ${supabaseServiceKey}`,
        "Content-Type": "application/json",
        "Prefer": "return=representation"
      },
      body: JSON.stringify({
        full_name: customer_name,
        phone: customer_phone.trim(),
        email: customer_email || null,
        status: 'Nuevo',
        visit_count: 1,
        last_treatment: treatmentName
      })
    });
    const newClientData = await newClientRes.json();
    if (newClientData && newClientData.length > 0) {
      client_id = newClientData[0].id;
    } else {
      throw new Error("No se pudo registrar al nuevo cliente.");
    }
  }

  // 3. Registrar la reserva del turno cambiando estado a Pendiente
  const patchAppRes = await fetch(`${supabaseUrl}/rest/v1/appointments?id=eq.${appointment_id}`, {
    method: 'PATCH',
    headers: {
      "apikey": supabaseServiceKey,
      "Authorization": `Bearer ${supabaseServiceKey}`,
      "Content-Type": "application/json",
      "Prefer": "return=representation"
    },
    body: JSON.stringify({
      client_id: client_id,
      customer_name: customer_name,
      customer_phone: customer_phone.trim(),
      customer_email: customer_email || null,
      status: 'Pendiente',
      notes: notes || null
    })
  });
  const updatedApp = await patchAppRes.json();

  // 4. Crear un cobro pendiente en la tabla de pagos
  await fetch(`${supabaseUrl}/rest/v1/payments`, {
    method: 'POST',
    headers: {
      "apikey": supabaseServiceKey,
      "Authorization": `Bearer ${supabaseServiceKey}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      appointment_id: appointment_id,
      client_id: client_id,
      concept: treatmentName,
      amount: appointment.price,
      status: 'Pendiente'
    })
  });

  return {
    success: true,
    mensaje: "Turno reservado con éxito. Estado: Pendiente de confirmación.",
    turno: {
      id: appointment_id,
      fecha: appointment.appointment_date,
      hora: appointment.appointment_time ? appointment.appointment_time.substring(0, 5) : '',
      servicio: treatmentName,
      cliente: customer_name
    }
  };
} catch (error) {
  return { error: error.message };
}
